import { ArrowLeft, BookOpen, Shuffle, Users, Plus, RefreshCw, Crown } from "lucide-react";
import { PkRoom } from "@/types/pk";

interface Props {
  waitingRooms: PkRoom[];
  refreshing: boolean;
  onRefresh: () => void;
  onJoin: (room: PkRoom) => void;
  onCreate: () => void;
  onBack: () => void;
}

export function PkLobbyView({
  waitingRooms,
  refreshing,
  onRefresh,
  onJoin,
  onCreate,
  onBack,
}: Props) {
  return (
    <div className="h-screen bg-gradient-to-br from-slate-900 via-emerald-950 to-slate-900 flex flex-col overflow-hidden">
      <div className="flex items-center gap-3 p-4">
        <button
          onClick={onBack}
          className="w-10 h-10 rounded-full bg-slate-800/60 border border-slate-600/50 flex items-center justify-center text-white hover:scale-105 transition-transform"
        >
          <ArrowLeft size={20} />
        </button>
        <h1 className="text-xl font-bold text-slate-100">单词 PK</h1>
      </div>

      <div className="flex-1 min-h-0 p-6 overflow-y-auto">
        <div className="w-full max-w-sm mx-auto flex flex-col gap-6">
          <div className="flex items-center justify-between">
            <p className="text-slate-300 font-medium">等待中的房间</p>
            <button
              onClick={onRefresh}
              disabled={refreshing}
              className="p-2 rounded-lg bg-slate-800/40 text-slate-400 hover:text-slate-200 transition-colors disabled:opacity-50"
            >
              <RefreshCw size={16} className={refreshing ? "animate-spin" : ""} />
            </button>
          </div>

          {waitingRooms.length === 0 ? (
            <div className="bg-slate-800/40 border border-slate-700 rounded-2xl p-8 text-center">
              <Users size={32} className="text-slate-600 mx-auto mb-3" />
              <p className="text-slate-500">暂无等待中的房间</p>
              <p className="text-slate-600 text-xs mt-1">点击下方按钮创建一个吧</p>
            </div>
          ) : (
            <div className="space-y-3">
              {waitingRooms.map((r) => (
                <button
                  key={r.id}
                  onClick={() => onJoin(r)}
                  className="w-full p-4 rounded-2xl border border-slate-700 bg-slate-800/40 text-left hover:border-emerald-500/50 hover:bg-slate-800/60 transition-all active:scale-[0.98]"
                >
                  <div className="flex items-start justify-between mb-2">
                    <div className="flex items-center gap-2">
                      <div className="w-8 h-8 rounded-full bg-gradient-to-br from-emerald-400 to-teal-500 flex items-center justify-center">
                        <span className="text-white text-xs font-bold">
                          {r.hostNickname?.slice(0, 1)}
                        </span>
                      </div>
                      <div>
                        <p className="text-slate-200 font-medium text-sm">{r.hostNickname}</p>
                        <div className="flex items-center gap-1 mt-0.5">
                          {r.sourceType === "import" ? (
                            <BookOpen size={12} className="text-emerald-400" />
                          ) : (
                            <Shuffle size={12} className="text-emerald-400" />
                          )}
                          <span className="text-slate-500 text-xs">
                            {r.sourceType === "import"
                              ? r.importRecordTitle || "导入记录"
                              : "房主单词本"}
                          </span>
                        </div>
                      </div>
                    </div>
                    <Crown size={14} className="text-amber-400" />
                  </div>
                  <div className="flex items-center gap-2 text-xs">
                    <span className="px-2 py-0.5 rounded-full bg-slate-700/50 text-slate-400">
                      {r.questionCount} 题
                    </span>
                    <span className="px-2 py-0.5 rounded-full bg-slate-700/50 text-slate-400">
                      {r.timePerQuestion} 秒/题
                    </span>
                    <span className="px-2 py-0.5 rounded-full bg-emerald-500/15 text-emerald-400">
                      等待加入
                    </span>
                  </div>
                </button>
              ))}
            </div>
          )}

          <button
            onClick={onCreate}
            className="w-full py-4 bg-gradient-to-r from-emerald-500 to-teal-500 text-white font-bold text-lg rounded-2xl shadow-lg hover:scale-105 active:scale-95 transition-all flex items-center justify-center gap-2"
          >
            <Plus size={22} />
            创建房间
          </button>
        </div>
      </div>
    </div>
  );
}

export type { Props as PkLobbyViewProps };
