import { useState } from "react";
import { Users, X } from "lucide-react";
import { useOnlineStore } from "@/store/useOnlineStore";
import { getUserInfo } from "@/utils/userInfo";
import { locationToText } from "@/hooks/useOnlinePresence";

export default function OnlinePlayersBadge() {
  const [open, setOpen] = useState(false);
  const players = useOnlineStore((s) => s.players);
  const isConnected = useOnlineStore((s) => s.isConnected);
  const userInfo = getUserInfo();

  const count = players.length;

  return (
    <>
      <div className="absolute top-4 left-4 z-20">
        <button
          onClick={() => setOpen(true)}
          className="flex items-center gap-2 px-3 py-2 rounded-full bg-slate-800/60 backdrop-blur-sm border border-slate-600/50 hover:bg-slate-800/80 transition-all"
        >
          <div className="relative">
            <Users size={18} className={isConnected ? "text-emerald-400" : "text-slate-400"} />
            {isConnected && count > 0 && (
              <span className="absolute -top-1 -right-1 min-w-[16px] h-4 px-1 bg-emerald-500 rounded-full flex items-center justify-center text-white text-[10px] font-bold border border-emerald-300">
                {count}
              </span>
            )}
          </div>
          <span className="text-slate-200 text-sm font-medium">
            {isConnected ? `${count} 人在线` : "连接中..."}
          </span>
        </button>
      </div>

      {open && (
        <div className="fixed inset-0 z-50 flex items-start sm:items-center justify-center p-4 pt-20 sm:pt-4">
          <div
            className="absolute inset-0 bg-black/60 backdrop-blur-sm"
            onClick={() => setOpen(false)}
          />
          <div className="relative w-full max-w-sm bg-gradient-to-br from-slate-800 to-slate-900 border border-slate-600/50 rounded-2xl shadow-2xl overflow-hidden">
            <div className="flex items-center justify-between p-4 border-b border-slate-700/50">
              <div className="flex items-center gap-2">
                <Users size={20} className="text-emerald-400" />
                <h2 className="text-lg font-bold text-slate-100">在线玩家</h2>
                <span className="px-2 py-0.5 bg-emerald-500/20 rounded-full text-emerald-300 text-xs font-medium">
                  {count}
                </span>
              </div>
              <button
                onClick={() => setOpen(false)}
                className="p-1.5 rounded-lg hover:bg-slate-700/50 text-slate-400 hover:text-slate-200 transition-all"
              >
                <X size={18} />
              </button>
            </div>

            <div className="max-h-80 overflow-y-auto">
              {players.length === 0 ? (
                <div className="p-8 text-center">
                  <Users size={32} className="mx-auto text-slate-600 mb-2" />
                  <p className="text-slate-500 text-sm">暂无在线玩家</p>
                </div>
              ) : (
                <div className="p-2">
                  {players.map((p) => {
                    const isMe = p.uuid === userInfo.uuid;
                    return (
                      <div
                        key={p.uuid}
                        className={`flex items-center gap-3 px-3 py-2.5 rounded-xl mb-1 ${
                          isMe
                            ? "bg-violet-500/20 border border-violet-400/30"
                            : "hover:bg-slate-700/30"
                        }`}
                      >
                        <div className="w-9 h-9 rounded-full bg-gradient-to-br from-slate-600 to-slate-700 flex items-center justify-center shrink-0">
                          <span className="text-slate-200 font-bold text-sm">
                            {p.nickname.slice(0, 1)}
                          </span>
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2">
                            <p className="text-slate-100 font-medium truncate">
                              {p.nickname}
                            </p>
                            {isMe && (
                              <span className="px-1.5 py-0.5 bg-violet-500/30 rounded text-violet-300 text-[10px] font-medium">
                                我
                              </span>
                            )}
                          </div>
                          <p className="text-slate-500 text-xs">
                            {locationToText(p.location)}
                          </p>
                        </div>
                        <div className="w-2 h-2 rounded-full bg-emerald-400 shrink-0" />
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </>
  );
}
