import { useState, useEffect, useMemo, useCallback } from "react";
import { useFarmStore } from "@/store/useFarmStore";
import { useGameStore } from "@/store/useGameStore";
import { showToast } from "@/utils/toast";
import { SeedType, SEED_CONFIGS } from "@/types/game";

export type TabType = "field" | "shop" | "warehouse";

export const createSellAmounts = (): Record<SeedType, number> => ({
  cabbage: 1, sunflower: 1, tomato: 1, corn: 1, strawberry: 1,
  carrot: 1, cucumber: 1, watermelon: 1, grapes: 1, eggplant: 1, kiwi: 1,
});

export function useFarmUI(shouldReset: boolean) {
  const [activeTab, setActiveTab] = useState<TabType>("field");
  const [selectedSeed, setSelectedSeed] = useState<SeedType | null>(null);
  const [selectedPlot, setSelectedPlot] = useState<number | null>(null);
  const [tick, setTick] = useState(0);
  const [showQuiz, setShowQuiz] = useState(false);
  const [sellAmounts, setSellAmounts] = useState<Record<SeedType, number>>(createSellAmounts);

  const sunlight = useGameStore((s) => s.sunlight);
  const seedInventory = useFarmStore((s) => s.seedInventory);
  const plantedCrops = useFarmStore((s) => s.plantedCrops);
  const warehouse = useFarmStore((s) => s.warehouse);
  const totalPlots = useFarmStore((s) => s.totalPlots);
  const unlockedSeeds = useFarmStore((s) => s.unlockedSeeds);
  const openedPlots = useFarmStore((s) => s.openedPlots);
  const loadFarm = useFarmStore((s) => s.loadFarm);
  const unlockSeed = useFarmStore((s) => s.unlockSeed);
  const unlockPlot = useFarmStore((s) => s.unlockPlot);
  const buySeed = useFarmStore((s) => s.buySeed);
  const plantSeed = useFarmStore((s) => s.plantSeed);
  const harvestCrop = useFarmStore((s) => s.harvestCrop);
  const clearStolenRecord = useFarmStore((s) => s.clearStolenRecord);
  const waterCrop = useFarmStore((s) => s.waterCrop);
  const weedCrop = useFarmStore((s) => s.weedCrop);
  const fertilizeCrop = useFarmStore((s) => s.fertilizeCrop);
  const sellFruit = useFarmStore((s) => s.sellFruit);
  const sellAllFruits = useFarmStore((s) => s.sellAllFruits);
  const getGrowthStage = useFarmStore((s) => s.getGrowthStage);
  const getStageProgress = useFarmStore((s) => s.getStageProgress);
  const getTimeRemaining = useFarmStore((s) => s.getTimeRemaining);
  const isReadyToHarvest = useFarmStore((s) => s.isReadyToHarvest);
  const getCropAtPlot = useFarmStore((s) => s.getCropAtPlot);
  const stolenRecords = useFarmStore((s) => s.stolenRecords);
  const debugAddSunlight = useFarmStore((s) => s.debugAddSunlight);
  const debugAdvanceCrop = useFarmStore((s) => s.debugAdvanceCrop);
  const debugRipenCrop = useFarmStore((s) => s.debugRipenCrop);

  // 重置状态
  useEffect(() => {
    if (shouldReset) {
      loadFarm();
      setActiveTab("field");
      setSelectedSeed(null);
    }
  }, [shouldReset, loadFarm]);

  // 刷新计时器（每分钟 tick 一次，更新剩余时间显示）
  useEffect(() => {
    const interval = setInterval(() => setTick((t) => t + 1), 60000);
    return () => clearInterval(interval);
  }, []);

  const showMsg = useCallback((text: string, type: "success" | "error") => {
    showToast(text, type);
  }, []);

  const handleBuy = useCallback((seedType: SeedType) => {
    const result = buySeed(seedType);
    showMsg(result.message, result.success ? "success" : "error");
  }, [buySeed, showMsg]);

  const handleUnlockSeed = useCallback((seedType: SeedType) => {
    const result = unlockSeed(seedType);
    showMsg(result.message, result.success ? "success" : "error");
  }, [unlockSeed, showMsg]);

  const handleUnlockPlot = useCallback(() => {
    const result = unlockPlot();
    showMsg(result.message, result.success ? "success" : "error");
  }, [unlockPlot, showMsg]);

  const handlePlotClick = useCallback((plotIndex: number) => {
    const crop = getCropAtPlot(plotIndex);
    if (crop) {
      if (isReadyToHarvest(crop)) {
        const result = harvestCrop(crop.id);
        showMsg(result.message, result.success ? "success" : "error");
      } else {
        setSelectedPlot(plotIndex);
      }
      return;
    }
    // 被偷的地块：点击清除记录，类似收获流程
    const stolen = stolenRecords.find((r) => r.plotIndex === plotIndex);
    if (stolen) {
      const result = clearStolenRecord(plotIndex);
      showMsg(result.message, "error");
      return;
    }
    if (selectedSeed) {
      const result = plantSeed(selectedSeed, plotIndex);
      if (result.success) {
        showMsg(result.message, "success");
        setSelectedSeed(null);
      } else {
        showMsg(result.message, "error");
      }
    }
  }, [selectedSeed, getCropAtPlot, isReadyToHarvest, harvestCrop, plantSeed, showMsg, stolenRecords, clearStolenRecord]);

  const handleWater = useCallback(() => {
    if (selectedPlot === null) return;
    const crop = getCropAtPlot(selectedPlot);
    if (!crop) return;
    const result = waterCrop(crop.id);
    showMsg(result.message, result.success ? "success" : "error");
  }, [selectedPlot, getCropAtPlot, waterCrop, showMsg]);

  const handleWeed = useCallback(() => {
    if (selectedPlot === null) return;
    const crop = getCropAtPlot(selectedPlot);
    if (!crop) return;
    const result = weedCrop(crop.id);
    showMsg(result.message, result.success ? "success" : "error");
  }, [selectedPlot, getCropAtPlot, weedCrop, showMsg]);

  const handleFertilize = useCallback(() => {
    if (selectedPlot === null) return;
    const crop = getCropAtPlot(selectedPlot);
    if (!crop) return;
    const result = fertilizeCrop(crop.id);
    showMsg(result.message, result.success ? "success" : "error");
  }, [selectedPlot, getCropAtPlot, fertilizeCrop, showMsg]);

  const handleSellAll = useCallback(() => {
    const result = sellAllFruits();
    if (result.totalCoins > 0) {
      showMsg(`全部卖出，获得 ${result.totalCoins} 积分`, "success");
    } else {
      showMsg("仓库是空的", "error");
    }
  }, [sellAllFruits, showMsg]);

  const handleSell = useCallback((seedType: SeedType) => {
    const amount = sellAmounts[seedType] || 1;
    const result = sellFruit(seedType, amount);
    if (result.success) {
      showMsg(result.message, "success");
      setSellAmounts((prev) => ({ ...prev, [seedType]: 1 }));
    } else {
      showMsg(result.message, "error");
    }
  }, [sellAmounts, sellFruit, showMsg]);

  const adjustSellAmount = useCallback((seedType: SeedType, delta: number) => {
    const max = warehouse[seedType] || 0;
    setSellAmounts((prev) => {
      const next = Math.max(1, Math.min(max, (prev[seedType] || 1) + delta));
      return { ...prev, [seedType]: next };
    });
  }, [warehouse]);

  const totalWarehouseValue = useMemo(() => {
    let total = 0;
    for (const seedType of Object.keys(warehouse) as SeedType[]) {
      total += (warehouse[seedType] || 0) * SEED_CONFIGS[seedType].fruitCoins;
    }
    return total;
  }, [warehouse, tick]);

  return {
    // 状态
    activeTab, setActiveTab,
    selectedSeed, setSelectedSeed,
    selectedPlot, setSelectedPlot,
    showMsg,
    tick, setTick,
    showQuiz, setShowQuiz,
    sellAmounts,
    // 数据
    sunlight, seedInventory, plantedCrops, warehouse,
    totalPlots, unlockedSeeds, openedPlots,
    // 操作
    handleBuy, handleUnlockSeed, handleUnlockPlot,
    handlePlotClick, handleSellAll, handleSell, adjustSellAmount,
    handleWater, handleWeed, handleFertilize,
    getGrowthStage, getStageProgress, getTimeRemaining,
    isReadyToHarvest, getCropAtPlot,
    debugAddSunlight, debugAdvanceCrop, debugRipenCrop,
    totalWarehouseValue,
  };
}
